/**
 * How Single corded sickle (`hitotsu-kama`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/hitotsu-kama";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"An upright sickle, its blade sweeping out to the left from the top of the bound handle. A cord loops once to the right of the handle and twice to the left of it; one end hangs loose and the other runs through the eye at the foot.","ja":"鎌を立て、巻きのある柄の上から刃を左へ大きく反らせます。紐は柄の右で一度、左で二度輪をつくり、一方の端は垂らし、もう一方は柄の下の穴に通します。"};

export default construction;
export { construction, description };
